const queryClient = new QueryClient();

const cn = (...classes: Array<string | false | null | undefined>) => classes.filter(Boolean).join(' ');
const fmtTime = (value?: string | null) => value ? new Date(value).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '—';
const fmtDate = (value?: string | null) => value ? new Date(value).toLocaleDateString([], { month: 'short', day: 'numeric' }) : '—';

function LoadingLines({ count = 4 }: { count?: number }) {
  return <div className="space-y-3" data-testid="loading-skeleton">{Array.from({ length: count }).map((_, i) => <div key={i} className="h-4 animate-pulse rounded bg-muted" style={{ width: `${72 - i * 9}%` }} />)}</div>;
}

function EmptyState({ title, detail, icon: Icon = CircleDashed }: { title: string; detail: string; icon?: typeof CircleDashed }) {
  return <div className="flex min-h-40 flex-col items-center justify-center gap-2 p-6 text-center" data-testid="empty-state"><Icon className="h-7 w-7 text-muted-foreground" /><p className="text-sm font-semibold">{title}</p><p className="max-w-xs text-xs text-muted-foreground">{detail}</p></div>;
}

function QueryError({ message = 'Unable to load this panel.' }: { message?: string }) {
  return <div className="flex items-center gap-2 rounded-lg border border-destructive/30 bg-destructive/5 p-3 text-xs text-destructive" data-testid="status-error"><AlertCircle className="h-4 w-4 shrink-0" />{message}</div>;
}

function StatusDot({ status }: { status: string }) {
  const live = ['running', 'active', 'connected'].includes(status);
  const good = ['complete', 'completed', 'success', 'stopped'].includes(status);
  return <span className={cn('inline-block h-2 w-2 rounded-full', live && 'bg-primary mtech-pulse', good && 'bg-emerald-500', !live && !good && 'bg-amber-400')} />;
}

function BrandMark({ compact = false }: { compact?: boolean }) {
  return <div className={cn('flex items-center gap-3', compact && 'justify-center')} data-testid="brand-mark">
    <div className={cn('relative shrink-0 overflow-hidden rounded-xl bg-slate-950 shadow-lg shadow-primary/10', compact ? 'h-9 w-9' : 'h-12 w-[78px]')}>
      <img
        src="/mtech-logo.png"
        alt="MTech — Build smarter together"
        className={cn('h-full w-full', compact ? 'scale-[2.1] object-cover object-[50%_22%]' : 'object-contain')}
      />
    </div>
  </div>;
}

function ProjectPicker({ projects, currentId, onCreate, collapsed = false }: { projects: Project[]; currentId?: string; onCreate: () => void; collapsed?: boolean }) {
  const [open, setOpen] = useState(false);
  const current = projects.find((p) => p.id === currentId) ?? projects[0];
  if (collapsed) return <button type="button" onClick={onCreate} title={current?.name ?? 'Create workspace'} data-testid="button-project-picker-collapsed" className="mx-auto flex h-9 w-9 items-center justify-center rounded-lg bg-primary/15 text-primary hover:bg-primary/25"><Boxes className="h-4 w-4" /></button>;
  return <div className="group relative">
    <button type="button" onClick={() => setOpen((value) => !value)} aria-expanded={open} data-testid="button-project-picker" className="flex w-full items-center justify-between rounded-lg border border-sidebar-border bg-sidebar-accent/50 px-3 py-2 text-left hover:bg-sidebar-accent">
      <span className="flex min-w-0 items-center gap-2"><span className="flex h-7 w-7 items-center justify-center rounded-md bg-primary/15 text-primary"><Boxes className="h-4 w-4" /></span><span className="min-w-0"><span className="block truncate text-xs font-bold text-sidebar-accent-foreground">{current?.name ?? 'Select workspace'}</span><span className="block font-mono text-[10px] text-sidebar-foreground/60">{current?.branch ?? 'no branch'}</span></span></span><ChevronDown className="h-4 w-4 shrink-0 text-sidebar-foreground/60" />
    </button>
    <div className={cn('absolute left-0 right-0 top-full z-30 mt-1 rounded-lg border border-sidebar-border bg-sidebar p-1 shadow-2xl transition', open ? 'visible opacity-100' : 'invisible opacity-0 group-focus-within:visible group-focus-within:opacity-100 group-hover:visible group-hover:opacity-100')}>
      {projects.map((project) => <Link key={project.id} href={`/projects/${project.id}`} data-testid={`link-project-${project.id}`} className="flex items-center justify-between rounded-md px-2 py-2 text-xs text-sidebar-foreground hover:bg-sidebar-accent"><span className="flex items-center gap-2"><StatusDot status={project.status} />{project.name}</span><span className="font-mono text-[10px] text-sidebar-foreground/50">{project.progress}%</span></Link>)}
      <button type="button" onClick={onCreate} data-testid="button-create-project-sidebar" className="mt-1 flex w-full items-center gap-2 border-t border-sidebar-border px-2 py-2 pt-2 text-xs font-semibold text-sidebar-primary hover:text-sidebar-accent-foreground"><Plus className="h-3.5 w-3.5" />New workspace</button>
    </div>
  </div>;
}

function Sidebar({ projects, currentId, onCreate, open, onToggle, collapsed }: { projects: Project[]; currentId?: string; onCreate: () => void; open: boolean; onToggle: () => void; collapsed: boolean }) {
  const [location] = useLocation();
  const llm = useGetLlmStatus();
  const runtimeConnected = Boolean(llm.data?.connected);
  const nav = [
    { href: '/', label: 'Workspace', icon: Code2 },
    { href: '/dashboard', label: 'Command deck', icon: Gauge },
    { href: '/projects', label: 'Workspaces', icon: Layers3 },
    { href: '/settings', label: 'Settings', icon: Settings2 },
  ];
  return <aside className={cn('fixed inset-y-0 left-0 z-50 flex w-[260px] shrink-0 flex-col border-r border-sidebar-border bg-sidebar text-sidebar-foreground shadow-2xl shadow-black/30 transition-[width,transform] duration-200 lg:relative lg:inset-auto lg:z-auto lg:translate-x-0 lg:shadow-none', open ? 'translate-x-0' : '-translate-x-full', collapsed && 'lg:w-[76px]')}>
    <div className={cn('flex h-[72px] items-center border-b border-sidebar-border px-5', collapsed ? 'justify-center lg:px-0' : 'justify-between')}><BrandMark compact={collapsed} /><button type="button" onClick={onToggle} className={cn('rounded-md p-1.5 text-sidebar-foreground/55 hover:bg-sidebar-accent hover:text-sidebar-accent-foreground', collapsed && 'lg:hidden')} aria-label="Hide navigation" data-testid="button-sidebar-collapse"><PanelLeft className="h-4 w-4" /></button></div>
    <div className={cn('p-4', collapsed && 'lg:px-0')}><div className={cn('mb-2 px-1 font-mono text-[10px] uppercase tracking-[.16em] text-sidebar-foreground/45', collapsed && 'lg:hidden')}>Active workspace</div><ProjectPicker projects={projects} currentId={currentId} onCreate={onCreate} collapsed={collapsed} /></div>
    <nav className={cn('space-y-1 px-3', collapsed && 'lg:px-2')} aria-label="Primary navigation">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} title={collapsed ? label : undefined} data-testid={`link-nav-${label.toLowerCase().replace(' ', '-')}`} className={cn('flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-semibold', collapsed && 'lg:justify-center lg:px-0', (location === href || (href === '/' && location.startsWith('/projects/'))) ? 'bg-sidebar-accent text-sidebar-accent-foreground' : 'text-sidebar-foreground/65 hover:bg-sidebar-accent/70 hover:text-sidebar-accent-foreground')}><Icon className="h-4 w-4 shrink-0" /><span className={cn(collapsed && 'lg:hidden')}>{label}</span>{href === '/' && <span className={cn('ml-auto h-1.5 w-1.5 rounded-full bg-primary', collapsed && 'lg:hidden')} />}</Link>)}</nav>
     <div className={cn('mt-8 px-4', collapsed && 'lg:hidden')}><div className="mb-2 px-1 font-mono text-[10px] uppercase tracking-[.16em] text-sidebar-foreground/45">Project telemetry</div><div className="rounded-xl border border-sidebar-border bg-sidebar-accent/35 p-3"><div className="flex items-center justify-between text-xs"><span className="flex items-center gap-2"><span className={cn('h-2 w-2 rounded-full', runtimeConnected ? 'bg-primary mtech-pulse' : 'bg-amber-400')} />Orchestrator</span><span className={cn('font-mono text-[10px]', runtimeConnected ? 'text-primary' : 'text-amber-400')}>{runtimeConnected ? 'ONLINE' : 'OFFLINE'}</span></div><div className="mt-3 h-1 rounded-full bg-sidebar-border"><div className={cn('h-1 rounded-full bg-primary transition-all', runtimeConnected ? 'w-full' : 'w-0')} /></div><div className="mt-2 flex justify-between font-mono text-[10px] text-sidebar-foreground/45"><span>Local Colab</span><span>{llm.data?.latency ? `${llm.data.latency}ms` : 'not checked'}</span></div></div></div>
    <div className={cn('mt-auto border-t border-sidebar-border p-4', collapsed && 'lg:px-2')}><Link href="/settings/llm" title={collapsed ? 'Local Colab connection' : undefined} data-testid="link-sidebar-llm" className={cn('flex items-center gap-3 rounded-lg px-3 py-2 text-xs text-sidebar-foreground/60 hover:bg-sidebar-accent hover:text-sidebar-accent-foreground', collapsed && 'lg:justify-center lg:px-0')}><Wifi className="h-4 w-4 shrink-0 text-primary" /><span className={cn(collapsed && 'lg:hidden')}>Local Colab connection</span><span className={cn('ml-auto h-1.5 w-1.5 rounded-full bg-primary', collapsed && 'lg:hidden')} /></Link><div className={cn('mt-4 flex items-center gap-2 px-3 text-[10px] text-sidebar-foreground/35', collapsed && 'lg:hidden')}><div className="flex h-6 w-6 items-center justify-center rounded-full bg-sidebar-accent font-bold text-sidebar-primary">EC</div>engineer console<span className="ml-auto"><MoreHorizontal className="h-4 w-4" /></span></div></div>
  </aside>;
}

const ShellContext = createContext<{ sidebarOpen: boolean; toggleSidebar: () => void }>({ sidebarOpen: true, toggleSidebar: () => undefined });
const useShell = () => useContext(ShellContext);

function TopBar({ title, subtitle, onCreate }: { title: string; subtitle?: string; onCreate?: () => void }) {
  const [, setLocation] = useLocation();
  const { sidebarOpen, toggleSidebar } = useShell();
  return <header className="flex min-h-[66px] items-center justify-between border-b border-border bg-card/80 px-3 backdrop-blur md:px-5"><div className="flex min-w-0 items-center gap-2.5"><button type="button" className="rounded-md p-1.5 text-muted-foreground hover:bg-muted hover:text-foreground" onClick={toggleSidebar} data-testid="button-toggle-sidebar" aria-label={sidebarOpen ? 'Hide navigation' : 'Show navigation'}><PanelLeft className="h-4 w-4" /></button><div className="min-w-0"><h1 className="truncate text-base font-extrabold tracking-tight">{title}</h1>{subtitle && <p className="truncate text-[11px] text-muted-foreground">{subtitle}</p>}</div></div><div className="flex items-center gap-2"><div className="hidden items-center gap-2 rounded-full border border-border bg-background/50 px-3 py-1.5 text-[10px] font-semibold text-muted-foreground sm:flex"><Command className="h-3 w-3" /><span>Quick search</span><kbd className="rounded bg-muted px-1.5 py-0.5 font-mono">⌘K</kbd></div><button type="button" onClick={() => title === 'Workspaces' ? onCreate?.() : setLocation('/projects')} data-testid="button-create-project-top" className="flex items-center gap-1.5 rounded-lg bg-primary px-3 py-2 text-xs font-bold text-primary-foreground shadow-sm hover:-translate-y-0.5 hover:bg-primary/90"><Plus className="h-3.5 w-3.5" /><span className="hidden sm:inline">New workspace</span></button></div></header>;
}

function Shell({ children, currentId }: { children: ReactNode; currentId?: string }) {
  const [createOpen, setCreateOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(() => typeof window === 'undefined' || window.innerWidth >= 1024);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const projectsQuery = useListProjects();
  const projects = projectsQuery.data ?? [];
  const toggleSidebar = () => { setSidebarOpen((open) => !open); setSidebarCollapsed((collapsed) => !collapsed); };
  return <ShellContext.Provider value={{ sidebarOpen, toggleSidebar }}><div className="mtech-shell flex overflow-hidden"><div className={cn('fixed inset-0 z-40 bg-black/55 backdrop-blur-[2px] lg:hidden', !sidebarOpen && 'hidden')} onClick={() => setSidebarOpen(false)} aria-hidden="true" /><Sidebar projects={projects} currentId={currentId} onCreate={() => setCreateOpen(true)} open={sidebarOpen} onToggle={toggleSidebar} collapsed={sidebarCollapsed} /><main className="min-w-0 flex-1 overflow-hidden">{children}</main>{createOpen && <CreateProjectDialog onClose={() => setCreateOpen(false)} />}</div></ShellContext.Provider>;
}

function CreateProjectDialog({ onClose }: { onClose: () => void }) {
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [, setLocation] = useLocation();
  const create = useCreateProject();
  const submit = (event: FormEvent) => { event.preventDefault(); if (!name.trim()) return; create.mutate({ data: { name: name.trim(), description } }, { onSuccess: (project) => { queryClient.invalidateQueries({ queryKey: getListProjectsQueryKey() }); onClose(); setLocation(`/projects/${project.id}`); } }); };
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" data-testid="dialog-create-project"><form onSubmit={submit} className="mtech-card w-full max-w-md rounded-2xl p-6"><div className="mb-5 flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.16em] text-primary">Workspace bootstrap</p><h2 className="mt-1 text-xl font-extrabold">Start a new build</h2></div><button type="button" onClick={onClose} data-testid="button-close-create-project"><X className="h-5 w-5 text-muted-foreground" /></button></div><label className="mb-4 block text-xs font-bold">Workspace name<input value={name} onChange={(e) => setName(e.target.value)} autoFocus required placeholder="e.g. Atlas Control Plane" data-testid="input-project-name" className="mt-1.5 w-full rounded-lg border border-input bg-background px-3 py-2.5 text-sm outline-none ring-primary/20 focus:ring-4" /></label><label className="mb-5 block text-xs font-bold">Mission brief<textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="What should the agents ship?" data-testid="input-project-description" className="mt-1.5 min-h-24 w-full resize-none rounded-lg border border-input bg-background px-3 py-2.5 text-sm outline-none ring-primary/20 focus:ring-4" /></label><div className="flex justify-end gap-2"><button type="button" onClick={onClose} data-testid="button-cancel-create-project" className="rounded-lg px-3 py-2 text-xs font-bold text-muted-foreground hover:bg-muted">Cancel</button><button disabled={create.isPending} type="submit" data-testid="button-submit-create-project" className="flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-xs font-bold text-primary-foreground disabled:opacity-50">{create.isPending && <Loader2 className="h-3.5 w-3.5 animate-spin" />}Create workspace</button></div>{create.isError && <p className="mt-3 text-xs text-destructive">Workspace could not be created. Try again.</p>}</form></div>;
}

function WorkspacePage({ projectId }: { projectId?: string }) {
  const projectsQuery = useListProjects();
  const projectQuery = useGetProject(projectId ?? '', { query: { enabled: Boolean(projectId), queryKey: getGetProjectQueryKey(projectId ?? '') } });
  const project = projectId ? projectQuery.data : projectsQuery.data?.[0];
  if (projectsQuery.isLoading || (projectId && projectQuery.isLoading)) return <Shell><TopBar title="Workspace" onCreate={() => undefined} /><div className="p-6"><LoadingLines count={7} /></div></Shell>;
  if (projectsQuery.isError || (projectId && projectQuery.isError)) return <Shell><TopBar title="Workspace" onCreate={() => undefined} /><div className="p-6"><QueryError message="Project index is offline." /></div></Shell>;
  if (!project) return <Shell><TopBar title="Workspace" onCreate={() => undefined} /><div className="p-6"><EmptyState title="No workspaces yet" detail="Create your first workspace to connect the orchestrator." icon={Boxes} /></div></Shell>;
  return <Shell currentId={project.id}><WorkspaceContent project={project} /></Shell>;
}

function WorkspaceContent({ project }: { project: Project }) {
  const [mobilePanel, setMobilePanel] = useState<'chat' | 'preview'>('chat');
  const [sourceOpen, setSourceOpen] = useState(false);
  const [sourceTab, setSourceTab] = useState<'files' | 'code'>('files');
  const [activityOpen, setActivityOpen] = useState(false);
  const [selectedFile, setSelectedFile] = useState<ProjectFile | undefined>(project.files?.find((f) => f.kind === 'file'));
  const [message, setMessage] = useState('');
  const [chat, setChat] = useState<Array<{ role: 'user' | 'assistant'; content: string }>>([{ role: 'assistant', content: `Workspace synchronized. I’m ready to coordinate the next move in ${project.name}.` }]);
  const chatMutation = useChatWithLlm();
  const previewQuery = useGetPreview(project.id);
  const start = useStartPreview(); const stop = useStopPreview(); const restart = useRestartPreview();
  const preview = previewQuery.data;
  const send = (event: FormEvent) => { event.preventDefault(); if (!message.trim() || chatMutation.isPending) return; const content = message.trim(); setMessage(''); setChat((old) => [...old, { role: 'user', content }]); chatMutation.mutate({ data: { projectId: project.id, message: content, history: chat.map((m) => ({ role: m.role, content: m.content })) } }, { onSuccess: (response) => setChat((old) => [...old, { role: 'assistant', content: response.message }]) }); };
  const previewAction = (kind: 'start' | 'stop' | 'restart') => { const mutation = kind === 'start' ? start : kind === 'stop' ? stop : restart; mutation.mutate({ projectId: project.id }, { onSuccess: (next) => queryClient.setQueryData(getGetPreviewQueryKey(project.id), next) }); };
  const fileCount = project.files?.filter((f) => f.kind === 'file').length ?? 0;
  return <div className="flex h-dvh min-h-0 flex-col"><TopBar title={project.name} subtitle={`${project.branch}  ·  ${fileCount} files  ·  ${project.progress}% coordinated`} onCreate={() => undefined} /><div className="flex shrink-0 items-center gap-1 border-b border-border bg-card px-3 py-2 lg:hidden"><button type="button" onClick={() => setMobilePanel('chat')} data-testid="button-panel-chat" className={cn('rounded-md px-3 py-1.5 text-xs font-bold', mobilePanel === 'chat' && 'bg-primary text-primary-foreground')}>Commands</button><button type="button" onClick={() => setMobilePanel('preview')} data-testid="button-panel-preview" className={cn('rounded-md px-3 py-1.5 text-xs font-bold', mobilePanel === 'preview' && 'bg-primary text-primary-foreground')}>Preview</button></div><div className="relative grid min-h-0 flex-1 overflow-hidden lg:grid-cols-[minmax(320px,.78fr)_minmax(0,1.22fr)]">
     <section className={cn('flex min-h-0 min-w-0 flex-col border-r border-border bg-card/45', mobilePanel !== 'chat' && 'hidden lg:flex')}><div className="flex h-11 shrink-0 items-center justify-between border-b border-border px-4"><span className="flex items-center gap-2 text-xs font-extrabold"><MessageSquare className="h-4 w-4 text-primary" />Orchestrator</span><span className="flex items-center gap-1.5 font-mono text-[10px] text-primary"><span className="h-1.5 w-1.5 rounded-full bg-primary" />LOCAL COLAB</span></div><div className="mtech-scroll flex-1 space-y-4 overflow-auto p-4">{chat.map((item, index) => <div key={`${item.role}-${index}`} className={cn('mtech-reveal flex gap-2.5', item.role === 'user' && 'flex-row-reverse')}><div className={cn('mt-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-md', item.role === 'assistant' ? 'bg-primary/15 text-primary' : 'bg-accent/25 text-accent-foreground')} >{item.role === 'assistant' ? <Bot className="h-3.5 w-3.5" /> : <span className="text-[10px] font-bold">EC</span>}</div><div className={cn('max-w-[84%] rounded-xl px-3 py-2.5 text-xs leading-relaxed', item.role === 'assistant' ? 'rounded-tl-sm bg-card text-foreground shadow-sm' : 'rounded-tr-sm bg-primary text-primary-foreground')}>{item.content}</div></div>)}{chatMutation.isPending && <div className="flex gap-2.5"><div className="flex h-6 w-6 items-center justify-center rounded-md bg-primary/15 text-primary"><Bot className="h-3.5 w-3.5" /></div><div className="rounded-xl rounded-tl-sm bg-card px-3 py-2.5"><span className="flex gap-1"><i className="h-1.5 w-1.5 animate-bounce rounded-full bg-primary" /><i className="h-1.5 w-1.5 animate-bounce rounded-full bg-primary [animation-delay:120ms]" /><i className="h-1.5 w-1.5 animate-bounce rounded-full bg-primary [animation-delay:240ms]" /></span></div></div>}{chatMutation.isError && <QueryError message="Local Colab did not answer. Check the LLM connection in settings." />}</div><form onSubmit={send} className="shrink-0 border-t border-border p-3"><div className="relative"><textarea value={message} onChange={(e) => setMessage(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(e); } }} placeholder="Ask the orchestrator to inspect, plan, or build..." data-testid="input-chat-message" className="min-h-20 w-full resize-none rounded-xl border border-input bg-background px-3 py-3 pr-11 text-xs outline-none focus:border-primary focus:ring-2 focus:ring-primary/15" /><button type="submit" disabled={!message.trim() || chatMutation.isPending} data-testid="button-send-chat" className="absolute bottom-2.5 right-2.5 flex h-7 w-7 items-center justify-center rounded-lg bg-primary text-primary-foreground disabled:opacity-40"><Send className="h-3.5 w-3.5" /></button></div><div className="mt-2 flex items-center justify-between px-1 font-mono text-[9px] text-muted-foreground"><span>SHIFT + ENTER for newline</span><span className="flex items-center gap-1"><ShieldCheck className="h-3 w-3" />private runtime</span></div></form></section>
      <section className={cn('relative flex min-h-0 min-w-0 flex-col bg-card/55', mobilePanel !== 'preview' && 'hidden lg:flex')}><PreviewPanel projectId={project.id} preview={preview} loading={previewQuery.isLoading} onAction={previewAction} /><AgentStatus projectId={project.id} />{activityOpen && <ActivityStrip projectId={project.id} />}
       <div className="absolute right-3 top-3 z-30 flex flex-col gap-1.5 rounded-xl border border-border bg-background/90 p-1.5 shadow-2xl backdrop-blur"><button type="button" onClick={() => { setSourceTab('files'); setSourceOpen((open) => !open); }} data-testid="button-toggle-files" className={cn('flex items-center gap-2 rounded-lg px-2.5 py-2 text-[10px] font-bold', sourceOpen && sourceTab === 'files' ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted hover:text-foreground')}><FolderOpen className="h-3.5 w-3.5" />Files</button><button type="button" onClick={() => { setSourceTab('code'); setSourceOpen((open) => !open); }} data-testid="button-toggle-code" className={cn('flex items-center gap-2 rounded-lg px-2.5 py-2 text-[10px] font-bold', sourceOpen && sourceTab === 'code' ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted hover:text-foreground')}><Code2 className="h-3.5 w-3.5" />Code</button><button type="button" onClick={() => setActivityOpen((open) => !open)} data-testid="button-toggle-activity" className={cn('flex items-center gap-2 rounded-lg px-2.5 py-2 text-[10px] font-bold', activityOpen ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted hover:text-foreground')}><Activity className="h-3.5 w-3.5" />Activity</button></div>
         {sourceOpen && <div className="absolute inset-y-0 right-0 z-20 flex w-[min(480px,calc(100%-16px))] min-w-0 flex-col border-l border-primary/20 bg-background/98 shadow-[-18px_0_40px_rgba(0,0,0,.45)]"><div className="flex h-11 shrink-0 items-center justify-between border-b border-border px-3"><div className="flex items-center gap-1.5"><button type="button" onClick={() => setSourceTab('files')} data-testid="button-source-explorer" className={cn('rounded-md px-2.5 py-1.5 text-[10px] font-bold', sourceTab === 'files' && 'bg-primary/15 text-primary')}>Explorer</button><button type="button" onClick={() => setSourceTab('code')} data-testid="button-source-editor" className={cn('rounded-md px-2.5 py-1.5 text-[10px] font-bold', sourceTab === 'code' && 'bg-primary/15 text-primary')}>Editor</button></div><button type="button" onClick={() => setSourceOpen(false)} aria-label="Hide files and code" data-testid="button-close-source-drawer" className="rounded-md p-1.5 text-muted-foreground hover:bg-muted hover:text-foreground"><PanelRight className="h-4 w-4" /></button></div>{sourceTab === 'files' ? <FileExplorer projectId={project.id} files={project.files ?? []} selected={selectedFile?.path} onSelect={(file) => { setSelectedFile(file); setSourceTab('code'); }} /> : <CodeEditor projectId={project.id} file={selectedFile} />}</div>}
     </section>
  </div></div>;
}

function FileExplorer({ projectId, files, selected, onSelect }: { projectId: string; files: ProjectFile[]; selected?: string; onSelect: (file: ProjectFile) => void }) {
  const folders = useMemo(() => Array.from(new Set(files.filter((f) => f.kind === 'folder').map((f) => f.path))), [files]);
  return <div className="mtech-scroll overflow-auto border-r border-border bg-card/30 p-2"><div className="mb-2 flex items-center justify-between px-2"><span className="font-mono text-[9px] uppercase tracking-widest text-muted-foreground">Explorer</span><a href={getDownloadProjectZipUrl(projectId)} download="mtech-workspace.zip" title="Download workspace ZIP" className="flex items-center gap-1 rounded px-2 py-1 text-[9px] font-bold text-primary hover:bg-primary/10"><Download className="h-3.5 w-3.5" />ZIP</a></div>{folders.map((folder) => <div key={folder} className="flex items-center gap-1.5 rounded px-2 py-1.5 text-[10px] font-semibold text-muted-foreground"><ChevronDown className="h-3 w-3" /><Folder className="h-3 w-3 text-accent" />{folder.replace(/\/$/, '')}</div>)}{files.filter((f) => f.kind === 'file').map((file) => <div key={file.path} className="group flex items-center rounded hover:bg-muted"><button type="button" onClick={() => onSelect(file)} data-testid={`button-file-${file.path.replace(/[^a-z0-9]/gi, '-')}`} className={cn('flex min-w-0 flex-1 items-center gap-1.5 rounded px-2 py-1.5 text-left text-[10px] text-muted-foreground', selected === file.path && 'bg-primary/10 font-bold text-primary')}><FileCode2 className="h-3 w-3 shrink-0" /><span className="truncate">{file.path}</span></button><a href={getDownloadProjectFileUrl(projectId, { path: file.path })} download title={`Download ${file.path}`} className="mr-1 rounded p-1 text-muted-foreground opacity-0 transition group-hover:opacity-100 hover:bg-primary/10 hover:text-primary"><Download className="h-3 w-3" /></a></div>)}{files.length === 0 && <EmptyState title="No files indexed" detail="The workspace scanner returned no downloadable files." icon={FolderOpen} />}</div>;
}

function CodeEditor({ projectId, file }: { projectId: string; file?: ProjectFile }) {
  const [content, setContent] = useState('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  useEffect(() => {
    let cancelled = false;
    if (!file) { setContent(''); return () => { cancelled = true; }; }
    setLoading(true);
    fetch(getDownloadProjectFileUrl(projectId, { path: file.path }))
      .then((response) => response.ok ? response.text() : Promise.reject(new Error('File unavailable')))
      .then((value) => { if (!cancelled) setContent(value); })
      .catch(() => { if (!cancelled) setContent('// Unable to load this file from the workspace.'); })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, [projectId, file?.path]);
  const save = async () => {
    if (!file) return;
    setSaving(true); setSaved(false);
    try {
      const response = await fetch(`/api/mtech/projects/${encodeURIComponent(projectId)}/files`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ path: file.path, content }) });
      if (!response.ok) throw new Error('File save failed');
      setSaved(true);
    } finally { setSaving(false); }
  };
  return <div className="mtech-scroll min-w-0 overflow-auto bg-background/35"><div className="flex h-9 items-center gap-2 border-b border-border bg-card/50 px-4 font-mono text-[10px] text-muted-foreground"><FileCode2 className="h-3 w-3 text-primary" />{file?.path ?? 'no file selected'}<span className="ml-auto">{file?.language ?? '—'}</span>{file && <button type="button" disabled={saving} onClick={save} className="rounded bg-primary/15 px-2 py-1 font-sans font-bold text-primary disabled:opacity-50">{saving ? 'Saving…' : saved ? 'Saved' : 'Save'}</button>}</div>{loading ? <div className="p-4"><LoadingLines count={6} /></div> : file ? <textarea value={content} onChange={(event) => { setContent(event.target.value); setSaved(false); }} spellCheck={false} aria-label={`Edit ${file.path}`} className="code-block min-h-[calc(100dvh-220px)] w-full resize-none border-0 bg-transparent p-4 font-mono text-[11px] leading-6 text-foreground/80 outline-none" /> : <EmptyState title="Select a file" detail="Choose a workspace file from Explorer to inspect its real contents." icon={FileCode2} />}</div>;
}

function ActivityStrip({ projectId }: { projectId: string }) {
  const query = useListActivity(projectId);
  const events = query.data ?? [];
  return <div className="border-t border-border bg-card/80"><div className="flex items-center justify-between border-b border-border px-4 py-2"><span className="flex items-center gap-2 text-[10px] font-extrabold uppercase tracking-widest"><Activity className="h-3.5 w-3.5 text-primary" />Activity log</span><Link href={`/projects/${projectId}/activity`} data-testid="link-view-activity" className="text-[10px] font-bold text-primary hover:underline">View all</Link></div><div className="mtech-scroll flex gap-4 overflow-auto p-3">{query.isLoading ? <LoadingLines count={2} /> : events.length ? events.slice(0, 3).map((event) => <div key={event.id} className="min-w-44 text-[10px]"><div className="flex items-center gap-1.5 font-bold"><StatusDot status={event.type} />{event.agent}</div><p className="mt-1 truncate text-muted-foreground">{event.action}</p><p className="mt-1 font-mono text-[9px] text-muted-foreground/60">{fmtTime(event.timestamp)}</p></div>) : <p className="px-1 text-[10px] text-muted-foreground">No agent events in this session.</p>}</div></div>;
}

function PreviewPanel({ projectId, preview, loading, onAction }: { projectId: string; preview?: PreviewStatus; loading: boolean; onAction: (kind: 'start' | 'stop' | 'restart') => void }) {
  const busy = !preview || preview.status === 'starting';
  return <div className="flex min-h-[460px] flex-col border-b border-border"><div className="flex h-11 items-center justify-between border-b border-border px-4"><span className="flex items-center gap-2 text-xs font-extrabold"><TerminalSquare className="h-4 w-4 text-primary" />Live preview</span><span className="flex items-center gap-1.5 font-mono text-[10px]"><StatusDot status={preview?.status ?? 'stopped'} />{preview?.status?.toUpperCase() ?? 'CHECKING'}</span></div><div className="mtech-scanline mtech-grid relative m-3 flex min-h-48 flex-1 items-center justify-center overflow-hidden rounded-xl border border-border bg-slate-950"><div className="absolute left-3 top-3 flex gap-1"><span className="h-2 w-2 rounded-full bg-rose-400/70" /><span className="h-2 w-2 rounded-full bg-amber-300/70" /><span className="h-2 w-2 rounded-full bg-primary/70" /></div>{loading ? <Loader2 className="h-5 w-5 animate-spin text-primary" /> : preview?.status === 'running' && preview.url ? <iframe title="MTech project preview" src={preview.url} className="h-full min-h-48 w-full border-0 bg-card" data-testid="iframe-project-preview" /> : <div className="relative z-10 text-center"><div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-xl border border-primary/20 bg-primary/10 text-primary"><Code2 className="h-6 w-6" /></div><p className="text-xs font-bold text-slate-200">Preview is parked</p><p className="mt-1 text-[10px] text-slate-400">Start the local runtime to inspect output</p></div>}</div><div className="flex items-center justify-between gap-3 px-3 pb-3"><span className="truncate font-mono text-[10px] text-muted-foreground">{preview?.url ?? 'localhost: waiting for port'}</span><div className="flex shrink-0 gap-1.5">{preview?.status === 'running' && preview.url && <button type="button" onClick={() => window.open(preview.url ?? '', '_blank', 'noopener,noreferrer')} data-testid="button-open-preview" className="flex items-center gap-1 rounded-md border border-primary/30 px-2 py-1.5 text-[10px] font-bold text-primary"><ExternalLink className="h-3 w-3" />Open</button>}<button type="button" disabled={busy || preview?.status === 'running'} onClick={() => onAction('start')} data-testid="button-start-preview" className="flex items-center gap-1 rounded-md border border-primary/30 px-2 py-1.5 text-[10px] font-bold text-primary disabled:opacity-40"><Play className="h-3 w-3" />Start</button><button type="button" disabled={busy || preview?.status !== 'running'} onClick={() => onAction('stop')} data-testid="button-stop-preview" className="flex items-center gap-1 rounded-md border border-border px-2 py-1.5 text-[10px] font-bold disabled:opacity-40"><Square className="h-3 w-3" />Stop</button><button type="button" disabled={busy} onClick={() => onAction('restart')} data-testid="button-restart-preview" className="flex items-center gap-1 rounded-md border border-border px-2 py-1.5 text-[10px] font-bold disabled:opacity-40"><RotateCcw className="h-3 w-3" />Restart</button></div></div></div>;
}

function AgentStatus({ projectId }: { projectId: string }) {
  const query = useListAgents(projectId);
  const agents = query.data ?? [];
  return <div className="flex min-h-0 flex-1 flex-col"><div className="flex items-center justify-between border-b border-border px-4 py-2.5"><span className="flex items-center gap-2 text-[10px] font-extrabold uppercase tracking-widest"><Cpu className="h-3.5 w-3.5 text-primary" />Agent status</span><Link href={`/projects/${projectId}/agents`} data-testid="link-view-agents" className="text-[10px] font-bold text-primary hover:underline">Inspect</Link></div><div className="mtech-scroll flex-1 space-y-2 overflow-auto p-3">{query.isLoading ? <LoadingLines count={4} /> : agents.length ? agents.map((agent) => <AgentRow key={agent.id} agent={agent} />) : <EmptyState title="Agents are queued" detail="Send a brief to wake the specialist crew." icon={Bot} />}</div></div>;
}

function AgentRow({ agent }: { agent: Agent }) {
  return <div className="mtech-card rounded-lg p-3" data-testid={`card-agent-${agent.id}`}><div className="flex items-start justify-between gap-2"><div className="flex items-center gap-2"><div className="flex h-7 w-7 items-center justify-center rounded-md bg-primary/10 text-primary"><Bot className="h-3.5 w-3.5" /></div><div><p className="text-xs font-bold">{agent.name}</p><p className="text-[10px] text-muted-foreground">{agent.role}</p></div></div><span className="flex items-center gap-1 font-mono text-[9px] text-muted-foreground"><StatusDot status={agent.status} />{agent.status}</span></div><div className="mt-3 flex items-center gap-2"><div className="h-1.5 flex-1 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${agent.progress}%` }} /></div><span className="font-mono text-[10px] text-muted-foreground">{agent.progress}%</span></div><p className="mt-2 truncate text-[10px] text-muted-foreground">{agent.currentTask || agent.lastAction}</p></div>;
}

function DashboardPage() {
  const projectsQuery = useListProjects();
  const health = useGetMtechHealth();
  const platformHealth = useHealthCheck();
  const llm = useGetLlmStatus();
  const projects = projectsQuery.data ?? [];
  const active = projects.filter((p) => p.status === 'active').length;
  const connected = Boolean(llm.data?.connected);
  const workspaceSync = projectsQuery.isSuccess ? 100 : 0;
  return <Shell><TopBar title="Command deck" subtitle="A live readout of your local engineering room" onCreate={() => undefined} /><div className="mtech-scroll mtech-grid min-h-[calc(100dvh-72px)] overflow-auto p-4 md:p-7"><div className="mtech-reveal mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-primary">MTECH / OPERATIONS</p><h2 className="mt-2 max-w-2xl text-3xl font-extrabold tracking-[-.04em] md:text-5xl">Build with your agents<br /><span className="text-primary">in the room.</span></h2><p className="mt-3 max-w-lg text-sm text-muted-foreground">Coordinate code, tasks, and previews through a private Local Colab runtime.</p></div><div className="flex items-center gap-2 rounded-xl border border-primary/20 bg-primary/5 px-4 py-3 text-xs"><StatusDot status={health.data?.status ?? (platformHealth.data?.status ?? 'running')} /><span className="font-semibold">MTech service {health.data?.status ?? 'connecting'}</span><span className="font-mono text-muted-foreground">{health.data?.version ?? '—'}</span></div></div><div className="mb-7 grid gap-3 sm:grid-cols-3"><Metric label="Active workspaces" value={String(active)} detail={`${projects.length} indexed`} icon={Layers3} /><Metric label="Agent throughput" value={`${projects.reduce((sum, p) => sum + p.progress, 0) ? Math.round(projects.reduce((sum, p) => sum + p.progress, 0) / Math.max(projects.length, 1)) : 0}%`} detail="average completion" icon={Zap} /><Metric label="Runtime" value={connected ? "ONLINE" : "OFFLINE"} detail={llm.data?.latency ? `${llm.data.latency}ms` : "connection status"} icon={Wifi} /></div><div className="grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><section className="mtech-card rounded-2xl"><div className="flex items-center justify-between border-b border-border p-5"><div><h3 className="font-extrabold">Workspace pulse</h3><p className="mt-1 text-xs text-muted-foreground">Projects currently in the orchestration queue.</p></div><Link href="/projects" data-testid="link-dashboard-projects" className="flex items-center gap-1 text-xs font-bold text-primary">All workspaces<ArrowUpRight className="h-3.5 w-3.5" /></Link></div>{projectsQuery.isLoading ? <div className="p-5"><LoadingLines count={4} /></div> : projects.length ? <div className="divide-y divide-border">{projects.slice(0, 5).map((project) => <ProjectRow key={project.id} project={project} />)}</div> : <EmptyState title="Your control room is quiet" detail="Create a workspace to give the orchestrator a mission." icon={Boxes} />}</section><section className="mtech-card rounded-2xl p-5"><div className="mb-5 flex items-center justify-between"><div><h3 className="font-extrabold">Runtime signal</h3><p className="mt-1 text-xs text-muted-foreground">The local loop at a glance.</p></div><Gauge className="h-5 w-5 text-primary" /></div><div className="space-y-5"><Signal label="Orchestrator" value={connected ? "ONLINE" : "OFFLINE"} progress={connected ? 100 : 0} /><Signal label="Source model" value={llm.data?.model ?? "UNCONFIGURED"} progress={connected ? 100 : 0} /><Signal label="Workspace sync" value={projectsQuery.isSuccess ? "READY" : "LOADING"} progress={workspaceSync} /></div><Link href="/settings/llm" data-testid="link-dashboard-llm" className="mt-7 flex items-center justify-center gap-2 rounded-lg border border-border py-2.5 text-xs font-bold hover:border-primary hover:text-primary"><Settings2 className="h-3.5 w-3.5" />Configure connection</Link></section></div></div></Shell>;
}

function Metric({ label, value, detail, icon: Icon }: { label: string; value: string; detail: string; icon: typeof Gauge }) { return <div className="mtech-card rounded-xl p-4"><div className="flex items-center justify-between"><span className="text-xs font-bold text-muted-foreground">{label}</span><Icon className="h-4 w-4 text-primary" /></div><div className="mt-3 flex items-baseline gap-2"><span className="text-2xl font-extrabold tracking-tight">{value}</span><span className="font-mono text-[10px] text-muted-foreground">{detail}</span></div></div>; }
function Signal({ label, value, progress }: { label: string; value: string; progress: number }) { return <div><div className="mb-2 flex items-center justify-between text-[10px]"><span className="font-semibold">{label}</span><span className="font-mono text-primary">{value}</span></div><div className="h-1.5 rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${progress}%` }} /></div></div>; }
function ProjectRow({ project }: { project: Project }) { return <Link href={`/projects/${project.id}`} data-testid={`link-dashboard-project-${project.id}`} className="flex items-center gap-4 p-4 hover:bg-muted/45"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10 text-primary"><Code2 className="h-4 w-4" /></div><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><span className="truncate text-sm font-bold">{project.name}</span><StatusDot status={project.status} /></div><p className="mt-1 truncate text-xs text-muted-foreground">{project.description || 'No mission brief yet.'}</p></div><div className="hidden w-32 sm:block"><div className="mb-1 flex justify-between font-mono text-[9px] text-muted-foreground"><span>{project.branch}</span><span>{project.progress}%</span></div><div className="h-1 rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${project.progress}%` }} /></div></div><ChevronRight className="h-4 w-4 text-muted-foreground" /></Link>; }

function ProjectsPage() {
  const query = useListProjects(); const [createOpen, setCreateOpen] = useState(false);
  const projects = query.data ?? [];
  return <Shell><TopBar title="Workspaces" subtitle="Projects are isolated runtimes for your agent crew" onCreate={() => setCreateOpen(true)} /><div className="mtech-scroll mtech-grid min-h-[calc(100dvh-72px)] overflow-auto p-4 md:p-7"><div className="mb-6 flex items-end justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-primary">PROJECT REGISTRY</p><h2 className="mt-2 text-2xl font-extrabold">Your workspaces</h2></div><span className="font-mono text-xs text-muted-foreground">{projects.length} indexed</span></div>{query.isLoading ? <LoadingLines count={7} /> : query.isError ? <QueryError /> : projects.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{projects.map((project) => <ProjectCard key={project.id} project={project} />)}<button type="button" onClick={() => setCreateOpen(true)} data-testid="button-create-project-card" className="flex min-h-48 flex-col items-center justify-center rounded-2xl border border-dashed border-border bg-card/35 text-muted-foreground hover:border-primary hover:bg-primary/5 hover:text-primary"><Plus className="mb-2 h-6 w-6" /><span className="text-sm font-bold">New workspace</span><span className="mt-1 text-xs">Give agents a fresh room</span></button></div> : <EmptyState title="No workspaces registered" detail="Create one to start coordinating local agents." icon={Boxes} />}</div>{createOpen && <CreateProjectDialog onClose={() => setCreateOpen(false)} />}</Shell>;
}
function ProjectCard({ project }: { project: Project }) { return <Link href={`/projects/${project.id}`} data-testid={`card-project-${project.id}`} className="mtech-card group rounded-2xl p-5"><div className="flex items-start justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-primary/10 text-primary"><Code2 className="h-5 w-5" /></div><span className="flex items-center gap-1.5 rounded-full bg-muted px-2 py-1 font-mono text-[9px] uppercase"><StatusDot status={project.status} />{project.status}</span></div><h3 className="mt-5 truncate font-extrabold">{project.name}</h3><p className="mt-1 min-h-10 text-xs leading-relaxed text-muted-foreground">{project.description || 'An agent workspace ready for a mission.'}</p><div className="mt-5 flex items-center justify-between font-mono text-[10px] text-muted-foreground"><span className="flex items-center gap-1"><GitBranch className="h-3 w-3" />{project.branch}</span><span>updated {fmtDate(project.updatedAt)}</span></div><div className="mt-3 h-1 rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all group-hover:bg-accent" style={{ width: `${project.progress}%` }} /></div></Link>; }

function ProjectSubnav({ project, current }: { project: Project; current: string }) { const base = `/projects/${project.id}`; return <div className="flex items-center gap-1 overflow-auto border-b border-border bg-card px-4 md:px-7"><Link href={base} data-testid="link-project-workspace" className={cn('whitespace-nowrap border-b-2 px-3 py-3 text-xs font-bold', current === 'workspace' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground')}>Workspace</Link><Link href={`${base}/tasks`} data-testid="link-project-tasks" className={cn('whitespace-nowrap border-b-2 px-3 py-3 text-xs font-bold', current === 'tasks' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground')}>Tasks</Link><Link href={`${base}/agents`} data-testid="link-project-agents" className={cn('whitespace-nowrap border-b-2 px-3 py-3 text-xs font-bold', current === 'agents' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground')}>Agents</Link><Link href={`${base}/activity`} data-testid="link-project-activity" className={cn('whitespace-nowrap border-b-2 px-3 py-3 text-xs font-bold', current === 'activity' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground')}>Activity</Link><span className="ml-auto hidden items-center gap-1.5 font-mono text-[10px] text-muted-foreground md:flex"><GitBranch className="h-3 w-3" />{project.branch}</span></div>; }

function ProjectLayout({ children, current, projectId }: { children: ReactNode; current: string; projectId: string }) {
  const projectQuery = useProject(projectId); const project = projectQuery.data;
  if (projectQuery.isLoading) return <Shell currentId={projectId}><TopBar title="Loading workspace" onCreate={() => undefined} /><div className="p-6"><LoadingLines count={7} /></div></Shell>;
  if (projectQuery.isError || !project) return <Shell currentId={projectId}><TopBar title="Workspace unavailable" onCreate={() => undefined} /><div className="p-6"><QueryError message="This workspace could not be found." /></div></Shell>;
  return <Shell currentId={projectId}><TopBar title={project.name} subtitle={project.description} onCreate={() => undefined} /><ProjectSubnav project={project} current={current} />{children}</Shell>;
}
function useProject(projectId: string) { return (requireProjectHook(projectId)); }
function requireProjectHook(projectId: string) { return useGetProjectCompat(projectId); }
function useGetProjectCompat(projectId: string) { 
  // Kept as a tiny wrapper so every project subview shares one query shape.
  // eslint-disable-next-line react-hooks/rules-of-hooks
  return useGetProject(projectId);
}

function TasksPage({ projectId }: { projectId: string }) { const query = useListTasks(projectId); const tasks = query.data ?? []; return <ProjectLayout current="tasks" projectId={projectId}><div className="mtech-scroll mtech-grid min-h-[calc(100dvh-120px)] overflow-auto p-4 md:p-7"><div className="mb-6 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-primary">EXECUTION GRAPH</p><h2 className="mt-2 text-2xl font-extrabold">Task graph</h2><p className="mt-1 text-xs text-muted-foreground">Every brief becomes a traceable unit of work.</p></div><div className="flex gap-2 text-[10px] font-mono text-muted-foreground"><span className="rounded bg-primary/10 px-2 py-1 text-primary">{tasks.filter((t) => ['running', 'planning'].includes(t.status)).length} active</span><span className="rounded bg-muted px-2 py-1">{tasks.length} total</span></div></div>{query.isLoading ? <LoadingLines count={7} /> : query.isError ? <QueryError /> : tasks.length ? <div className="space-y-3">{tasks.map((task) => <TaskCard key={task.id} task={task} />)}</div> : <EmptyState title="No tasks in the graph" detail="Send a build brief to the orchestrator to create the first task." icon={ClipboardList} />}</div></ProjectLayout>; }
function TaskCard({ task }: { task: AgentTask }) { const statusColor = ['completed'].includes(task.status) ? 'text-emerald-600 bg-emerald-500/10' : ['running', 'planning'].includes(task.status) ? 'text-primary bg-primary/10' : task.status === 'failed' ? 'text-destructive bg-destructive/10' : 'text-accent-foreground bg-accent/15'; return <div className="mtech-card flex flex-col gap-4 rounded-xl p-4 md:flex-row md:items-center" data-testid={`card-task-${task.id}`}><div className="flex items-start gap-3 md:w-[42%]"><div className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-muted font-mono text-[10px] text-muted-foreground">{task.id.slice(-3)}</div><div className="min-w-0"><h3 className="text-sm font-bold">{task.title}</h3><p className="mt-1 text-xs text-muted-foreground">{task.description}</p></div></div><div className="flex flex-1 items-center gap-3"><span className={cn('rounded-full px-2 py-1 font-mono text-[9px] uppercase', statusColor)}>{task.status}</span><span className={cn('rounded-full border px-2 py-1 font-mono text-[9px] uppercase', task.priority === 'high' && 'border-destructive/30 text-destructive', task.priority !== 'high' && 'border-border text-muted-foreground')}>{task.priority} priority</span><span className="ml-auto text-[10px] text-muted-foreground">attempt {task.attempts}</span></div></div>; }

function AgentsPage({ projectId }: { projectId: string }) { const query = useListAgents(projectId); const agents = query.data ?? []; return <ProjectLayout current="agents" projectId={projectId}><div className="mtech-scroll mtech-grid min-h-[calc(100dvh-120px)] overflow-auto p-4 md:p-7"><div className="mb-6"><p className="font-mono text-[10px] uppercase tracking-[.2em] text-primary">SPECIALIST CREW</p><h2 className="mt-2 text-2xl font-extrabold">Agent status</h2><p className="mt-1 text-xs text-muted-foreground">See what each specialist is doing and what changed.</p></div>{query.isLoading ? <LoadingLines count={6} /> : agents.length ? <div className="grid gap-4 md:grid-cols-2">{agents.map((agent) => <AgentDetail key={agent.id} agent={agent} />)}</div> : <EmptyState title="No specialists attached" detail="The orchestrator will attach agents as tasks enter the graph." icon={Bot} />}</div></ProjectLayout>; }
function AgentDetail({ agent }: { agent: Agent }) { return <div className="mtech-card rounded-2xl p-5" data-testid={`card-agent-detail-${agent.id}`}><div className="flex items-start justify-between"><div className="flex items-center gap-3"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-primary/10 text-primary"><Bot className="h-5 w-5" /></div><div><h3 className="font-extrabold">{agent.name}</h3><p className="text-xs text-muted-foreground">{agent.role}</p></div></div><span className="flex items-center gap-1.5 rounded-full bg-muted px-2 py-1 font-mono text-[9px] uppercase"><StatusDot status={agent.status} />{agent.status}</span></div><div className="mt-6 flex items-center justify-between"><span className="text-xs font-semibold text-muted-foreground">Current throughput</span><span className="font-mono text-sm font-bold text-primary">{agent.progress}%</span></div><div className="mt-2 h-2 rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${agent.progress}%` }} /></div><div className="mt-5 grid grid-cols-2 gap-3 border-t border-border pt-4"><div><p className="font-mono text-[9px] uppercase text-muted-foreground">Current task</p><p className="mt-1 truncate text-xs font-semibold">{agent.currentTask || 'Standing by'}</p></div><div><p className="font-mono text-[9px] uppercase text-muted-foreground">Changed files</p><p className="mt-1 text-xs font-semibold">{agent.changedFiles}</p></div></div><p className="mt-4 rounded-lg bg-muted/60 p-3 text-xs text-muted-foreground">{agent.lastAction || 'No recent action recorded.'}</p></div>; }

function ActivityPage({ projectId }: { projectId: string }) { const query = useListActivity(projectId); const events = query.data ?? []; return <ProjectLayout current="activity" projectId={projectId}><div className="mtech-scroll mtech-grid min-h-[calc(100dvh-120px)] overflow-auto p-4 md:p-7"><div className="mb-6"><p className="font-mono text-[10px] uppercase tracking-[.2em] text-primary">EVENT STREAM</p><h2 className="mt-2 text-2xl font-extrabold">Activity timeline</h2><p className="mt-1 text-xs text-muted-foreground">A chronological trace of agent decisions and system events.</p></div>{query.isLoading ? <LoadingLines count={8} /> : events.length ? <div className="relative ml-3 border-l border-border pl-7">{events.map((event) => <ActivityItem key={event.id} event={event} />)}</div> : <EmptyState title="No activity yet" detail="Agent actions will appear here as your workspace runs." icon={Activity} />}</div></ProjectLayout>; }
function ActivityItem({ event }: { event: ActivityEvent }) { return <div className="relative mb-6" data-testid={`event-activity-${event.id}`}><span className="absolute -left-[2.05rem] top-0.5 flex h-5 w-5 items-center justify-center rounded-full border border-border bg-card"><StatusDot status={event.type} /></span><div className="flex flex-wrap items-baseline justify-between gap-2"><div><span className="text-xs font-extrabold">{event.agent}</span><span className="mx-2 text-xs text-muted-foreground">/</span><span className="text-xs font-semibold text-primary">{event.action}</span></div><time className="font-mono text-[10px] text-muted-foreground">{fmtDate(event.timestamp)} {fmtTime(event.timestamp)}</time></div><p className="mt-1 text-xs leading-relaxed text-muted-foreground">{event.detail}</p></div>; }

function LlmSettingsPage() {
  const configQuery = useGetLlmConfig(); const statusQuery = useGetLlmStatus(); const modelsQuery = useGetLlmModelsCompat();
  const config = configQuery.data; const [form, setForm] = useState({ endpoint: '', model: '', timeout: 30000, maxTokens: 4096, temperature: .2 });
  useEffect(() => { if (config) setForm({ endpoint: config.endpoint, model: config.model, timeout: config.timeout, maxTokens: config.maxTokens, temperature: config.temperature }); }, [config]);
  const update = useUpdateLlmConfig(); const test = useTestLlmConnection(); const status = statusQuery.data;
  const save = (e: FormEvent) => { e.preventDefault(); update.mutate({ data: form }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetLlmConfigQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetLlmStatusQueryKey() }); } }); };
  return <Shell><TopBar title="Local Colab" subtitle="Configure the source model behind your orchestrator" onCreate={() => undefined} /><div className="mtech-scroll mtech-grid min-h-[calc(100dvh-72px)] overflow-auto p-4 md:p-7"><div className="mb-6 flex items-start justify-between gap-4"><div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-primary">RUNTIME SETTINGS</p><h2 className="mt-2 text-2xl font-extrabold">Local Colab connection</h2><p className="mt-1 max-w-lg text-xs leading-relaxed text-muted-foreground">MTech routes orchestration to your local inference endpoint. Credentials stay on the runtime.</p></div><div className={cn('hidden items-center gap-2 rounded-full border px-3 py-2 text-xs font-bold sm:flex', status?.connected ? 'border-primary/30 bg-primary/5 text-primary' : 'border-accent/30 bg-accent/5')}><StatusDot status={status?.connected ? 'connected' : 'offline'} />{status?.connected ? `Connected · ${status.latency ?? '—'}ms` : 'Connection not verified'}</div></div><div className="grid max-w-5xl gap-5 xl:grid-cols-[1fr_320px]"><form onSubmit={save} className="mtech-card rounded-2xl p-5 md:p-7"><div className="mb-6 flex items-center justify-between border-b border-border pb-4"><div><h3 className="font-extrabold">Endpoint configuration</h3><p className="mt-1 text-xs text-muted-foreground">Provider: {config?.provider ?? 'Local Colab'}</p></div><Wifi className="h-5 w-5 text-primary" /></div><label className="mb-5 block text-xs font-bold">Inference endpoint<input value={form.endpoint} onChange={(e) => setForm({ ...form, endpoint: e.target.value })} placeholder="http://127.0.0.1:11434/v1" data-testid="input-llm-endpoint" className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2.5 font-mono text-xs outline-none focus:border-primary focus:ring-2 focus:ring-primary/15" /></label><div className="mb-5 grid gap-4 md:grid-cols-[1fr_180px]"><label className="block text-xs font-bold">Model<select value={form.model} onChange={(e) => setForm({ ...form, model: e.target.value })} data-testid="select-llm-model" className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2.5 font-mono text-xs outline-none focus:border-primary">{(modelsQuery.data?.models ?? []).map((model) => <option key={model.id} value={model.id}>{model.id}</option>)}{!modelsQuery.data?.models?.length && <option value={form.model}>{form.model || 'discover models'}</option>}</select></label><label className="block text-xs font-bold">Timeout (ms)<input type="number" value={form.timeout} onChange={(e) => setForm({ ...form, timeout: Number(e.target.value) })} data-testid="input-llm-timeout" className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2.5 font-mono text-xs outline-none focus:border-primary" /></label></div><div className="mb-7 grid gap-4 md:grid-cols-2"><label className="block text-xs font-bold">Max tokens<input type="number" value={form.maxTokens} onChange={(e) => setForm({ ...form, maxTokens: Number(e.target.value) })} data-testid="input-llm-max-tokens" className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2.5 font-mono text-xs outline-none focus:border-primary" /></label><label className="block text-xs font-bold">Temperature<input type="number" min="0" max="2" step=".1" value={form.temperature} onChange={(e) => setForm({ ...form, temperature: Number(e.target.value) })} data-testid="input-llm-temperature" className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2.5 font-mono text-xs outline-none focus:border-primary" /></label></div><div className="flex flex-wrap gap-2"><button disabled={update.isPending} type="submit" data-testid="button-save-llm" className="flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground disabled:opacity-50">{update.isPending && <Loader2 className="h-3.5 w-3.5 animate-spin" />}Save configuration</button><button disabled={test.isPending} type="button" onClick={() => test.mutate(undefined, { onSuccess: (result) => { if (result.connected) queryClient.invalidateQueries({ queryKey: getGetLlmStatusQueryKey() }); } })} data-testid="button-test-llm" className="flex items-center gap-2 rounded-lg border border-border px-4 py-2.5 text-xs font-bold hover:border-primary hover:text-primary">{test.isPending ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <RefreshCw className="h-3.5 w-3.5" />}Test connection</button></div>{update.isSuccess && <p className="mt-4 flex items-center gap-1.5 text-xs font-semibold text-primary"><CheckCircle2 className="h-4 w-4" />Configuration saved to the local runtime.</p>}{test.isSuccess && <p className={cn('mt-4 flex items-center gap-1.5 text-xs font-semibold', test.data.connected ? 'text-primary' : 'text-destructive')}><StatusDot status={test.data.connected ? 'connected' : 'offline'} />{test.data.message}</p>}{(update.isError || test.isError) && <p className="mt-4 text-xs text-destructive">The runtime rejected the request. Confirm the endpoint and retry.</p>}</form><div className="space-y-5"><div className="mtech-card rounded-2xl p-5"><div className="mb-4 flex items-center gap-2"><ShieldCheck className="h-4 w-4 text-primary" /><h3 className="text-sm font-extrabold">Runtime posture</h3></div><div className="space-y-3 text-xs"><InfoRow label="Provider" value={status?.provider ?? 'Local Colab'} /><InfoRow label="API key" value={status?.apiKeyConfigured ? 'Configured' : 'Not required'} /><InfoRow label="Last check" value={status?.lastCheck ? fmtDate(status.lastCheck) : 'Not checked'} /><InfoRow label="Endpoint" value={status?.endpoint ?? form.endpoint ?? '—'} /></div></div><div className="rounded-2xl border border-primary/20 bg-primary/5 p-5"><div className="flex items-center gap-2 text-primary"><Zap className="h-4 w-4" /><p className="text-xs font-extrabold">Why Local Colab?</p></div><p className="mt-3 text-xs leading-relaxed text-muted-foreground">Your code and prompts stay inside your own runtime while MTech provides the control surface, task graph, and agent coordination.</p></div></div></div></div></Shell>;
}
function useGetLlmModelsCompat() { 
  // The generated client is the single source of truth for model discovery.
  // eslint-disable-next-line react-hooks/rules-of-hooks
  return useGetLlmModels();
}
function InfoRow({ label, value }: { label: string; value: string }) { return <div className="flex items-center justify-between gap-3"><span className="text-muted-foreground">{label}</span><span className="max-w-[170px] truncate text-right font-mono text-[10px]">{value}</span></div>; }

function SettingsPage() { const health = useGetMtechHealth(); return <Shell><TopBar title="Settings" subtitle="Tune the MTech control room" onCreate={() => undefined} /><div className="mtech-scroll mtech-grid min-h-[calc(100dvh-72px)] overflow-auto p-4 md:p-7"><div className="mb-7"><p className="font-mono text-[10px] uppercase tracking-[.2em] text-primary">SYSTEM PREFERENCES</p><h2 className="mt-2 text-2xl font-extrabold">Control room settings</h2></div><div className="grid max-w-4xl gap-4 md:grid-cols-2"><Link href="/settings/llm" data-testid="card-settings-llm" className="mtech-card group rounded-2xl p-5"><div className="flex items-center justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-primary/10 text-primary"><Wifi className="h-5 w-5" /></div><ArrowUpRight className="h-4 w-4 text-muted-foreground group-hover:text-primary" /></div><h3 className="mt-5 font-extrabold">Local Colab</h3><p className="mt-1 text-xs leading-relaxed text-muted-foreground">Configure your endpoint, model selection, timeouts, and test the live connection.</p></Link><div className="mtech-card rounded-2xl p-5"><div className="flex items-center justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-accent/20 text-accent-foreground"><ShieldCheck className="h-5 w-5" /></div><span className="rounded-full bg-primary/10 px-2 py-1 font-mono text-[9px] text-primary">READY</span></div><h3 className="mt-5 font-extrabold">MTech service</h3><p className="mt-1 text-xs leading-relaxed text-muted-foreground">Core service health and runtime identity.</p><div className="mt-4 flex items-center gap-2 text-xs"><StatusDot status={health.data?.status ?? 'running'} />{health.data?.service ?? 'mtech-orchestrator'}<span className="font-mono text-[10px] text-muted-foreground">{health.data?.version ?? '—'}</span></div></div></div></div></Shell>; }

function AppRouter() { return <RoutedErrorBoundary><Switch>
  <Route path="/" component={() => <WorkspacePage />} />
  <Route path="/dashboard" component={DashboardPage} />
  <Route path="/projects" component={ProjectsPage} />
  <Route path="/projects/:projectId/chat" component={() => { const { projectId = '' } = useParams(); return <WorkspacePage projectId={projectId} />; }} />
  <Route path="/projects/:projectId/workspace" component={() => { const { projectId = '' } = useParams(); return <WorkspacePage projectId={projectId} />; }} />
  <Route path="/projects/:projectId/files" component={() => { const { projectId = '' } = useParams(); return <WorkspacePage projectId={projectId} />; }} />
  <Route path="/projects/:projectId/preview" component={() => { const { projectId = '' } = useParams(); return <WorkspacePage projectId={projectId} />; }} />
  <Route path="/projects/:projectId/tasks" component={() => { const { projectId = '' } = useParams(); return <TasksPage projectId={projectId} />; }} />
  <Route path="/projects/:projectId/agents" component={() => { const { projectId = '' } = useParams(); return <AgentsPage projectId={projectId} />; }} />
  <Route path="/projects/:projectId/activity" component={() => { const { projectId = '' } = useParams(); return <ActivityPage projectId={projectId} />; }} />
  <Route path="/projects/:projectId/settings" component={SettingsPage} />
  <Route path="/projects/:projectId" component={() => { const { projectId = '' } = useParams(); return <WorkspacePage projectId={projectId} />; }} />
  <Route path="/agents/:agentId" component={DashboardPage} />
  <Route path="/agents" component={DashboardPage} />
  <Route path="/tasks/:taskId" component={DashboardPage} />
  <Route path="/tasks" component={DashboardPage} />
  <Route path="/settings/llm" component={LlmSettingsPage} />
  <Route path="/settings/agents" component={SettingsPage} />
  <Route path="/settings/security" component={SettingsPage} />
  <Route path="/settings/execution" component={SettingsPage} />
  <Route path="/settings/workspace" component={SettingsPage} />
  <Route path="/settings" component={SettingsPage} />
  <Route component={NotFound} />
</Switch></RoutedErrorBoundary>; }
function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><AppRouter /><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;